-- The public views of steam-database.ipynb, cell 7, in the owner's steam-collection repository, as that
-- cell builds them on the cell-2 schema with no store or wishlist categories: exec the cell with conn,
-- lookups={'store_categories': []} and item_counts={}. tests/steam_manager/db/reports/_parity.py
-- compares the reports with them.
CREATE VIEW v_app_scores AS
SELECT
    n.appid AS "appid",
    n.name AS "name",
    f.review_count AS "review_count",
    f.percent_positive AS "percent_positive",
    f.review_score AS "review_score",
    CASE WHEN f.review_score = 0 THEN IIF(f.review_count > 0, f.review_count || ' user reviews', 'No user reviews') ELSE (SELECT label FROM review_score AS r WHERE r.review_score = f.review_score) END AS "review_score_label",
    s.positive AS "positive",
    s.negative AS "negative",
    s.counts_exact AS "counts_exact",
    (s.positive + s.negative) AS "total_ratings",
    100 * (1.0 * s.positive / NULLIF((s.positive + s.negative), 0)) AS "avg_rating",
    IIF((s.positive + s.negative) > 0, (100.0 * s.positive + (SELECT AVG(positive + negative) FROM app_review_total WHERE positive + negative > 0) * (SELECT AVG(100.0 * positive / (positive + negative)) FROM app_review_total WHERE positive + negative > 0)) / ((s.positive + s.negative) + (SELECT AVG(positive + negative) FROM app_review_total WHERE positive + negative > 0)), NULL) AS "bayes_avg",
    100 * ((1.0 * s.positive / NULLIF((s.positive + s.negative), 0)) + 2.5758293035489004 * 2.5758293035489004 / (2 * (s.positive + s.negative)) - 2.5758293035489004 * sqrt(((1.0 * s.positive / NULLIF((s.positive + s.negative), 0)) * (1 - (1.0 * s.positive / NULLIF((s.positive + s.negative), 0))) + 2.5758293035489004 * 2.5758293035489004 / (4.0 * (s.positive + s.negative))) / (s.positive + s.negative))) / (1 + 2.5758293035489004 * 2.5758293035489004 / (s.positive + s.negative)) AS "wilson_score",
    (SELECT SUM(h.recommendations_up) FROM review_history AS h WHERE h.appid = n.appid AND NOT h.is_recent) AS "hist_positive",
    (SELECT SUM(h.recommendations_down) FROM review_history AS h WHERE h.appid = n.appid AND NOT h.is_recent) AS "hist_negative"
FROM app AS n
LEFT JOIN app_review_summary AS f ON f.appid = n.appid AND f.scope = 'filtered'
LEFT JOIN app_review_total AS s ON s.appid = n.appid;

CREATE VIEW v_games AS
SELECT
    s.appid AS "appid",
    a.name AS "name",
    a.type AS "type",
    a.is_listed AS "is_listed",
    COALESCE(f.review_count, 0) AS "review_count",
    IIF(f.review_count > 0, f.percent_positive, NULL) AS "percent_positive",
    s.positive AS "positive",
    s.negative AS "negative",
    s.counts_exact AS "counts_exact",
    (s.positive + s.negative) AS "total_ratings",
    100 * (1.0 * s.positive / NULLIF((s.positive + s.negative), 0)) AS "avg_rating",
    IIF((s.positive + s.negative) > 0, (100.0 * s.positive + (SELECT AVG(positive + negative) FROM app_review_total WHERE positive + negative > 0) * (SELECT AVG(100.0 * positive / (positive + negative)) FROM app_review_total WHERE positive + negative > 0)) / ((s.positive + s.negative) + (SELECT AVG(positive + negative) FROM app_review_total WHERE positive + negative > 0)), NULL) AS "bayes_avg",
    100 * ((1.0 * s.positive / NULLIF((s.positive + s.negative), 0)) + 2.5758293035489004 * 2.5758293035489004 / (2 * (s.positive + s.negative)) - 2.5758293035489004 * sqrt(((1.0 * s.positive / NULLIF((s.positive + s.negative), 0)) * (1 - (1.0 * s.positive / NULLIF((s.positive + s.negative), 0))) + 2.5758293035489004 * 2.5758293035489004 / (4.0 * (s.positive + s.negative))) / (s.positive + s.negative))) / (1 + 2.5758293035489004 * 2.5758293035489004 / (s.positive + s.negative)) AS "wilson_score",
    IIF(a.store_country = 'BR', COALESCE(p.original_price_in_cents, p.final_price_in_cents) / 100.0, NULL) AS "price",
    substr(a.steam_release_date, 1, 10) AS "steam_release_date",
    EXISTS (SELECT 1 FROM wishlist_item AS x WHERE x.appid = s.appid) AS "wishlist",
    EXISTS (SELECT 1 FROM owned_game AS x WHERE x.appid = s.appid) AS "owned",
    EXISTS (SELECT 1 FROM ignored_app AS x WHERE x.appid = s.appid) AS "ignored",
    EXISTS (SELECT 1 FROM followed_app AS x WHERE x.appid = s.appid) AS "followed",
    e.status AS "status",
    COALESCE(e.on_notion, 0) AS "on_notion"
FROM app_review_total AS s
JOIN app AS a ON a.appid = s.appid
LEFT JOIN app_review_summary AS f ON f.appid = s.appid AND f.scope = 'filtered'
LEFT JOIN app_offer AS o ON o.appid = s.appid AND o.is_best
LEFT JOIN offer_price AS p ON p.kind = o.kind AND p.id = o.id AND p.country = a.store_country
LEFT JOIN list_entry AS e ON e.appid = s.appid
ORDER BY s.appid;

CREATE VIEW v_wishlist AS
SELECT "appid", "priority", "date_added", "item_type", "success", "visible", "original_sort_order", "recommended_sort_order", "name", "bayes_avg", "wilson_score", "store_url_path", "store_url_slug", "type", "store_url_path_override", "unlisted", "is_free", "unvailable_for_country_restriction", "free_weekend", "review_count", "percent_positive", "review_score", "review_score_label", "language_review_count", "language_percent_positive", "language_review_score", "language_review_score_label", "unfiltered_review_count", "unfiltered_percent_positive", "unfiltered_review_score", "unfiltered_review_score_label", "packageid", "purchase_option_name", "final_price_in_cents", "formatted_final_price", "user_can_purchase_as_gift", "hide_discount_pct_for_compliance", "included_game_count", "must_purchase_as_set", "package_group", "price_cannot_be_displayed_as_discount", "free_with_master_sub_appid", "original_price_in_cents", "formatted_original_price", "discount_pct", "bundleid", "bundle_discount_pct", "price_before_bundle_discount", "formatted_price_before_bundle_discount", "combined_discount_pct", "steam_release_date", "original_release_date", "original_steam_release_date", "is_coming_soon", "is_early_access", "custom_release_date_message", "coming_soon_display", "mac_release_date", "release_from_early_access_date", "release_from_early_access_style", "linux_release_date", "is_preload", "short_description", "publishers", "developers", "franchises", "capsule_headline", "windows", "steam_deck_compat_category", "steam_os_compat_category", "steam_frame_compat_category", "steam_machine_compat_category", "mac", "steamos_linux", "vr_support.vrhmd", "vr_support.htc_vive", "vr_support.oculus_rift", "vr_support.windows_mr", "vr_support.valve_index", "vr_support.show_optional_vr_mode_notice", "vr_support.vrhmd_only", "demos", "parent_appid", "dlc_parent_appids", "standalone_demos", "playtests", "related_f2p.appid", "related_f2p.header_text", "related_f2p.description_text", "rating", "agency", "banned", "esrb_online_music_not_rated", "esrb_online_interactions_not_rated", "survey_interactive_elements", "required_age", "use_age_gate", "agency_rating", "rating_type", "extra.vetted", "extra.has_community_hub", "website", "extra.links_and_info.available_documents", "extra.links_and_info.genreids", "metacritic_score", "metacritic_url", "extra.metacritic.always_show", "extra.interactive_elements", "extra.drm_third_party_type", "extra.links_and_info.achievements_visible", "achievement_count", "extra.points_shop_eligible", "extra.controller_wizard_complete", "extra.anticheat.kernel_mode", "extra.anticheat.name", "extra.anticheat.name_loc", "extra.links_and_info.stats_url", "extra.links_and_info.online_manual_url", "extra.links_and_info.privacy_policy_url", "extra.item_store_eligible", "extra.item_store_show_featured", "extra.user_account_third_party", "extra.user_account_third_party_link_to_steam", "extra.links_and_info.manufacturers", "extra.links_and_info.health_warning_url", "extra.anticheat.uninstall_completely", "extra.steam_award", "extra.ai_generation_service.name", "extra.ai_generation_service.url", "extra.no_mouse_keyboard_support", "extra.refund_checks_ea_playtime", "extra.anticheat.boot_protection", "extra.anticheat.boot_protection_name", "extra.season_pass.appid", "genres", "is_followed", "hist_positive", "hist_negative", "current_players"
FROM (
    SELECT *, ROW_NUMBER() OVER (ORDER BY "priority" NULLS LAST, sort_position) AS "original_sort_order", ROW_NUMBER() OVER (ORDER BY
    sort_most_wanted DESC,
    "unlisted",
    "is_free",
    "is_coming_soon",
    "success" NULLS LAST,
    sort_price DESC NULLS LAST,
    "type" NULLS LAST,
    "bayes_avg" DESC NULLS LAST,
    "name" NULLS LAST,
    "priority" NULLS LAST,
    sort_position
) AS "recommended_sort_order"
    FROM (SELECT w.appid AS "appid",
    w.priority AS "priority",
    w.date_added AS "date_added",
    0 AS "item_type",
    COALESCE(a.success, 15) AS "success",
    COALESCE(a.success, 15) = 1 AS "visible",
    n.name AS "name",
    IIF((s.positive + s.negative) > 0, (100.0 * s.positive + (SELECT AVG(positive + negative) FROM app_review_total WHERE positive + negative > 0) * (SELECT AVG(100.0 * positive / (positive + negative)) FROM app_review_total WHERE positive + negative > 0)) / ((s.positive + s.negative) + (SELECT AVG(positive + negative) FROM app_review_total WHERE positive + negative > 0)), NULL) AS "bayes_avg",
    100 * ((1.0 * s.positive / NULLIF((s.positive + s.negative), 0)) + 2.5758293035489004 * 2.5758293035489004 / (2 * (s.positive + s.negative)) - 2.5758293035489004 * sqrt(((1.0 * s.positive / NULLIF((s.positive + s.negative), 0)) * (1 - (1.0 * s.positive / NULLIF((s.positive + s.negative), 0))) + 2.5758293035489004 * 2.5758293035489004 / (4.0 * (s.positive + s.negative))) / (s.positive + s.negative))) / (1 + 2.5758293035489004 * 2.5758293035489004 / (s.positive + s.negative)) AS "wilson_score",
    n.store_url_path AS "store_url_path",
    replace(n.store_url_path, rtrim(n.store_url_path, replace(n.store_url_path, '/', '')), '') AS "store_url_slug",
    a.type AS "type",
    a.store_url_path_override AS "store_url_path_override",
    a.unlisted AS "unlisted",
    a.is_free AS "is_free",
    IIF(a.appid IS NULL, 1, a.unavailable_for_country_restriction) AS "unvailable_for_country_restriction",
    IIF(a.free_weekend_start IS NULL, NULL, json_patch(json_object('start_time', CAST(strftime('%s', a.free_weekend_start) AS INTEGER), 'end_time', CAST(strftime('%s', a.free_weekend_end) AS INTEGER)), json_object('text', a.free_weekend_text, 'appid', a.free_weekend_appid))) AS "free_weekend",
    f.review_count AS "review_count",
    f.percent_positive AS "percent_positive",
    f.review_score AS "review_score",
    CASE WHEN f.review_score = 0 THEN IIF(f.review_count > 0, f.review_count || ' user reviews', 'No user reviews') ELSE (SELECT label FROM review_score AS r WHERE r.review_score = f.review_score) END AS "review_score_label",
    l.review_count AS "language_review_count",
    l.percent_positive AS "language_percent_positive",
    l.review_score AS "language_review_score",
    CASE WHEN l.review_score = 0 THEN IIF(l.review_count > 0, l.review_count || ' user reviews', 'No user reviews') ELSE (SELECT label FROM review_score AS r WHERE r.review_score = l.review_score) END AS "language_review_score_label",
    u.review_count AS "unfiltered_review_count",
    u.percent_positive AS "unfiltered_percent_positive",
    u.review_score AS "unfiltered_review_score",
    CASE WHEN u.review_score = 0 THEN IIF(u.review_count > 0, u.review_count || ' user reviews', 'No user reviews') ELSE (SELECT label FROM review_score AS r WHERE r.review_score = u.review_score) END AS "unfiltered_review_score_label",
    IIF(o.kind = 'package', o.id, NULL) AS "packageid",
    x.name AS "purchase_option_name",
    p.final_price_in_cents AS "final_price_in_cents",
    CASE WHEN p.final_price_in_cents IS NULL THEN NULL WHEN a.store_country = 'BR' THEN 'R$' || replace(printf('%,d', p.final_price_in_cents / 100), ',', '.') || ',' || printf('%02d', p.final_price_in_cents % 100) ELSE '$' || printf('%,d', p.final_price_in_cents / 100) || '.' || printf('%02d', p.final_price_in_cents % 100) END AS "formatted_final_price",
    p.user_can_purchase_as_gift AS "user_can_purchase_as_gift",
    p.hide_discount_pct_for_compliance AS "hide_discount_pct_for_compliance",
    p.included_game_count AS "included_game_count",
    x.must_purchase_as_set AS "must_purchase_as_set",
    o.package_group AS "package_group",
    p.price_cannot_be_displayed_as_discount AS "price_cannot_be_displayed_as_discount",
    x.free_with_master_sub_appid AS "free_with_master_sub_appid",
    p.original_price_in_cents AS "original_price_in_cents",
    CASE WHEN p.original_price_in_cents IS NULL THEN NULL WHEN a.store_country = 'BR' THEN 'R$' || replace(printf('%,d', p.original_price_in_cents / 100), ',', '.') || ',' || printf('%02d', p.original_price_in_cents % 100) ELSE '$' || printf('%,d', p.original_price_in_cents / 100) || '.' || printf('%02d', p.original_price_in_cents % 100) END AS "formatted_original_price",
    p.discount_pct AS "discount_pct",
    IIF(o.kind = 'bundle', o.id, NULL) AS "bundleid",
    p.bundle_discount_pct AS "bundle_discount_pct",
    p.price_before_bundle_discount AS "price_before_bundle_discount",
    CASE WHEN p.price_before_bundle_discount IS NULL THEN NULL WHEN a.store_country = 'BR' THEN 'R$' || replace(printf('%,d', p.price_before_bundle_discount / 100), ',', '.') || ',' || printf('%02d', p.price_before_bundle_discount % 100) ELSE '$' || printf('%,d', p.price_before_bundle_discount / 100) || '.' || printf('%02d', p.price_before_bundle_discount % 100) END AS "formatted_price_before_bundle_discount",
    p.combined_discount_pct AS "combined_discount_pct",
    a.steam_release_date AS "steam_release_date",
    a.original_release_date AS "original_release_date",
    a.original_steam_release_date AS "original_steam_release_date",
    a.is_coming_soon AS "is_coming_soon",
    a.is_early_access AS "is_early_access",
    a.custom_release_date_message AS "custom_release_date_message",
    a.coming_soon_display AS "coming_soon_display",
    a.mac_release_date AS "mac_release_date",
    CAST(strftime('%s', a.release_from_early_access_date) AS INTEGER) AS "release_from_early_access_date",
    a.release_from_early_access_style AS "release_from_early_access_style",
    a.linux_release_date AS "linux_release_date",
    a.is_preload AS "is_preload",
    t.short_description AS "short_description",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT IIF(c.creator_id IS NULL, json_object('name', c.name), json_object('name', c.name, 'creator_clan_account_id', c.creator_id)) AS item FROM app_credit AS ac JOIN credit AS c USING (credit_id) WHERE ac.appid = a.appid AND ac.role = 'publisher' ORDER BY ac.position)), '[]') AS "publishers",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT IIF(c.creator_id IS NULL, json_object('name', c.name), json_object('name', c.name, 'creator_clan_account_id', c.creator_id)) AS item FROM app_credit AS ac JOIN credit AS c USING (credit_id) WHERE ac.appid = a.appid AND ac.role = 'developer' ORDER BY ac.position)), '[]') AS "developers",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT IIF(c.creator_id IS NULL, json_object('name', c.name), json_object('name', c.name, 'creator_clan_account_id', c.creator_id)) AS item FROM app_credit AS ac JOIN credit AS c USING (credit_id) WHERE ac.appid = a.appid AND ac.role = 'franchise' ORDER BY ac.position)), '[]') AS "franchises",
    t.capsule_headline AS "capsule_headline",
    a.windows AS "windows",
    a.steam_deck_compat_category AS "steam_deck_compat_category",
    a.steam_os_compat_category AS "steam_os_compat_category",
    a.steam_frame_compat_category AS "steam_frame_compat_category",
    a.steam_machine_compat_category AS "steam_machine_compat_category",
    a.mac AS "mac",
    a.steamos_linux AS "steamos_linux",
    a.vr_vrhmd AS "vr_support.vrhmd",
    a.vr_htc_vive AS "vr_support.htc_vive",
    a.vr_oculus_rift AS "vr_support.oculus_rift",
    a.vr_windows_mr AS "vr_support.windows_mr",
    a.vr_valve_index AS "vr_support.valve_index",
    a.vr_show_optional_vr_mode_notice AS "vr_support.show_optional_vr_mode_notice",
    a.vr_vrhmd_only AS "vr_support.vrhmd_only",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT IIF(r.label IS NULL, json_object('appid', r.related_appid, 'show_above_purchase', json(IIF(r.show_above_purchase, 'true', 'false'))), json_object('appid', r.related_appid, 'label', r.label, 'show_above_purchase', json(IIF(r.show_above_purchase, 'true', 'false')))) AS item FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'demo' ORDER BY r.related_appid)), '[]') AS "demos",
    a.parent_appid AS "parent_appid",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT r.related_appid AS item FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'dlc_parent' ORDER BY r.related_appid)), '[]') AS "dlc_parent_appids",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT IIF(r.label IS NULL, json_object('appid', r.related_appid, 'show_above_purchase', json(IIF(r.show_above_purchase, 'true', 'false'))), json_object('appid', r.related_appid, 'label', r.label, 'show_above_purchase', json(IIF(r.show_above_purchase, 'true', 'false')))) AS item FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'standalone_demo' ORDER BY r.related_appid)), '[]') AS "standalone_demos",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT IIF(r.is_open IS NULL, json_object('appid', r.related_appid), json_object('appid', r.related_appid, 'is_open', json(IIF(r.is_open, 'true', 'false')))) AS item FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'playtest' ORDER BY r.related_appid)), '[]') AS "playtests",
    (SELECT r.related_appid FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'related_f2p') AS "related_f2p.appid",
    (SELECT r.header_text FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'related_f2p') AS "related_f2p.header_text",
    (SELECT r.description_text FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'related_f2p') AS "related_f2p.description_text",
    a.rating AS "rating",
    a.agency AS "agency",
    a.banned AS "banned",
    a.esrb_online_music_not_rated AS "esrb_online_music_not_rated",
    a.esrb_online_interactions_not_rated AS "esrb_online_interactions_not_rated",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT e.element AS item FROM app_interactive_element AS e WHERE e.appid = a.appid ORDER BY e.element)), '[]') AS "survey_interactive_elements",
    a.required_age AS "required_age",
    a.use_age_gate AS "use_age_gate",
    a.agency_rating AS "agency_rating",
    (SELECT r.rating_type FROM rating_agency AS r WHERE r.agency = a.agency) AS "rating_type",
    a.vetted AS "extra.vetted",
    a.has_community_hub AS "extra.has_community_hub",
    a.website AS "website",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT d.document AS item FROM app_document AS d WHERE d.appid = a.appid ORDER BY d.document)), '[]') AS "extra.links_and_info.available_documents",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT g.genreid AS item FROM app_genre AS g WHERE g.appid = a.appid ORDER BY g.position)), '[]') AS "extra.links_and_info.genreids",
    a.metacritic_score AS "metacritic_score",
    a.metacritic_url AS "metacritic_url",
    a.metacritic_always_show AS "extra.metacritic.always_show",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT e.element AS item FROM app_interactive_element AS e WHERE e.appid = a.appid ORDER BY e.element)), '[]') AS "extra.interactive_elements",
    a.drm_third_party_type AS "extra.drm_third_party_type",
    a.achievements_visible AS "extra.links_and_info.achievements_visible",
    a.achievement_count AS "achievement_count",
    a.points_shop_eligible AS "extra.points_shop_eligible",
    a.controller_wizard_complete AS "extra.controller_wizard_complete",
    a.anticheat_kernel_mode AS "extra.anticheat.kernel_mode",
    a.anticheat_name AS "extra.anticheat.name",
    (SELECT r.name_loc FROM anticheat AS r WHERE r.name = a.anticheat_name) AS "extra.anticheat.name_loc",
    a.stats_url AS "extra.links_and_info.stats_url",
    a.online_manual_url AS "extra.links_and_info.online_manual_url",
    a.privacy_policy_url AS "extra.links_and_info.privacy_policy_url",
    a.item_store_eligible AS "extra.item_store_eligible",
    a.item_store_show_featured AS "extra.item_store_show_featured",
    a.user_account_third_party AS "extra.user_account_third_party",
    a.user_account_third_party_link_to_steam AS "extra.user_account_third_party_link_to_steam",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT json_quote(m.name) AS item FROM app_manufacturer AS m WHERE m.appid = a.appid ORDER BY m.position)), '[]') AS "extra.links_and_info.manufacturers",
    a.health_warning_url AS "extra.links_and_info.health_warning_url",
    a.anticheat_uninstall_completely AS "extra.anticheat.uninstall_completely",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT json_object('voteid', w.voteid, 'award_year', w.award_year, 'localization', json_object('title', w.title)) AS item FROM app_steam_award AS w WHERE w.appid = a.appid ORDER BY w.position)), '[]') AS "extra.steam_award",
    a.ai_generation_service_name AS "extra.ai_generation_service.name",
    a.ai_generation_service_url AS "extra.ai_generation_service.url",
    a.no_mouse_keyboard_support AS "extra.no_mouse_keyboard_support",
    a.refund_checks_ea_playtime AS "extra.refund_checks_ea_playtime",
    a.anticheat_boot_protection AS "extra.anticheat.boot_protection",
    a.anticheat_boot_protection_name AS "extra.anticheat.boot_protection_name",
    (SELECT r.related_appid FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'season_pass') AS "extra.season_pass.appid",
    (SELECT group_concat(name, ', ') FROM (SELECT COALESCE(g.name, ag.genreid) AS name FROM app_genre AS ag JOIN genre AS g USING (genreid) WHERE ag.appid = a.appid ORDER BY ag.position)) AS "genres",
    EXISTS (SELECT 1 FROM followed_app AS x WHERE x.appid = n.appid) AS "is_followed",
    (SELECT SUM(h.recommendations_up) FROM review_history AS h WHERE h.appid = n.appid AND NOT h.is_recent) AS "hist_positive",
    (SELECT SUM(h.recommendations_down) FROM review_history AS h WHERE h.appid = n.appid AND NOT h.is_recent) AS "hist_negative",
    n.current_players AS "current_players",
    w.appid IN (SELECT m.appid FROM wishlist_item_category AS m JOIN wishlist_category AS c USING (categoryid) WHERE c.name = 'Most Wanted') AS "sort_most_wanted",
    COALESCE(p.original_price_in_cents, p.final_price_in_cents) AS "sort_price",
    w.position AS "sort_position" FROM wishlist_item AS w
JOIN app AS n ON n.appid = w.appid
LEFT JOIN app AS a ON a.appid = w.appid AND a.store_country = 'BR'
LEFT JOIN app_text AS t ON t.appid = a.appid
LEFT JOIN app_review_summary AS f ON f.appid = a.appid AND f.scope = 'filtered'
LEFT JOIN app_review_summary AS l ON l.appid = a.appid AND l.scope = 'language'
LEFT JOIN app_review_summary AS u ON u.appid = a.appid AND u.scope = 'unfiltered'
LEFT JOIN app_offer AS o ON o.appid = a.appid AND o.is_best
LEFT JOIN offer AS x ON x.kind = o.kind AND x.id = o.id
LEFT JOIN offer_price AS p ON p.kind = o.kind AND p.id = o.id AND p.country = a.store_country
LEFT JOIN app_review_total AS s ON s.appid = n.appid
)
)
ORDER BY "original_sort_order";

CREATE VIEW v_followed AS
SELECT
    w.appid AS "appid",
    n.name AS "name",
    a.type AS "type",
    a.is_listed AS "is_listed",
    IIF(s.appid IS NULL, a.is_free, COALESCE(a.is_free, 0)) AS "is_free",
    IIF(s.appid IS NULL, a.is_early_access, COALESCE(a.is_early_access, 0)) AS "is_early_access",
    IIF(s.appid IS NULL, a.is_coming_soon, COALESCE(a.is_coming_soon, 0)) AS "is_coming_soon",
    IIF(s.appid IS NULL, f.review_count, COALESCE(f.review_count, 0)) AS "review_count",
    IIF(f.review_count > 0, f.percent_positive, NULL) AS "percent_positive",
    s.positive AS "positive",
    s.negative AS "negative",
    s.counts_exact AS "counts_exact",
    (s.positive + s.negative) AS "total_ratings",
    100 * (1.0 * s.positive / NULLIF((s.positive + s.negative), 0)) AS "avg_rating",
    IIF((s.positive + s.negative) > 0, (100.0 * s.positive + (SELECT AVG(positive + negative) FROM app_review_total WHERE positive + negative > 0) * (SELECT AVG(100.0 * positive / (positive + negative)) FROM app_review_total WHERE positive + negative > 0)) / ((s.positive + s.negative) + (SELECT AVG(positive + negative) FROM app_review_total WHERE positive + negative > 0)), NULL) AS "bayes_avg",
    100 * ((1.0 * s.positive / NULLIF((s.positive + s.negative), 0)) + 2.5758293035489004 * 2.5758293035489004 / (2 * (s.positive + s.negative)) - 2.5758293035489004 * sqrt(((1.0 * s.positive / NULLIF((s.positive + s.negative), 0)) * (1 - (1.0 * s.positive / NULLIF((s.positive + s.negative), 0))) + 2.5758293035489004 * 2.5758293035489004 / (4.0 * (s.positive + s.negative))) / (s.positive + s.negative))) / (1 + 2.5758293035489004 * 2.5758293035489004 / (s.positive + s.negative)) AS "wilson_score",
    IIF(a.success IS NULL, NULL, 0) AS "item_type",
    a.success AS "success",
    IIF(a.success IS NULL, NULL, a.success = 1) AS "visible",
    a.store_country AS "store_country",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT d.descriptorid AS item FROM app_content_descriptor AS d WHERE d.appid = n.appid ORDER BY d.descriptorid)), '[]') AS "content_descriptorids",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT r.related_appid AS item FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'demo' ORDER BY r.related_appid)), '[]') AS "demo_appid",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT r.related_appid AS item FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'standalone_demo' ORDER BY r.related_appid)), '[]') AS "standalone_demo_appid",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT json_quote(d.descriptor) AS item FROM app_rating_descriptor AS d WHERE d.appid = a.appid ORDER BY d.position)), '[]') AS "descriptors",
    a.rating_interactive_elements AS "interactive_elements",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT json_object('discount_amount', CAST(d.discount_amount AS TEXT), 'discount_description', d.discount_description, 'discount_end_date', CAST(strftime('%s', d.discount_end_date) AS INTEGER)) AS item FROM offer_discount AS d WHERE d.kind = o.kind AND d.id = o.id AND d.country = a.store_country ORDER BY d.position)), '[]') AS "active_discounts",
    x.renewal_id AS "recurrence_info.packageid",
    x.billing_agreement_type AS "recurrence_info.billing_agreement_type",
    x.renewal_time_unit AS "recurrence_info.renewal_time_unit",
    x.renewal_time_period AS "recurrence_info.renewal_time_period",
    p.renewal_price_in_cents AS "recurrence_info.renewal_price_in_cents",
    CASE WHEN p.renewal_price_in_cents IS NULL THEN NULL WHEN a.store_country = 'BR' THEN 'R$' || replace(printf('%,d', p.renewal_price_in_cents / 100), ',', '.') || ',' || printf('%02d', p.renewal_price_in_cents % 100) ELSE '$' || printf('%,d', p.renewal_price_in_cents / 100) || '.' || printf('%02d', p.renewal_price_in_cents % 100) END AS "recurrence_info.formatted_renewal_price",
    (SELECT group_concat(name, ', ') FROM (SELECT COALESCE(g.name, ag.genreid) AS name FROM app_genre AS ag JOIN genre AS g USING (genreid) WHERE ag.appid = a.appid ORDER BY ag.position)) AS "genres",
    n.store_url_path AS "store_url_path",
    replace(n.store_url_path, rtrim(n.store_url_path, replace(n.store_url_path, '/', '')), '') AS "store_url_slug",
    a.store_url_path_override AS "store_url_path_override",
    a.unlisted AS "unlisted",
    a.unavailable_for_country_restriction AS "unvailable_for_country_restriction",
    IIF(a.free_weekend_start IS NULL, NULL, json_patch(json_object('start_time', CAST(strftime('%s', a.free_weekend_start) AS INTEGER), 'end_time', CAST(strftime('%s', a.free_weekend_end) AS INTEGER)), json_object('text', a.free_weekend_text, 'appid', a.free_weekend_appid))) AS "free_weekend",
    f.review_score AS "review_score",
    CASE WHEN f.review_score = 0 THEN IIF(f.review_count > 0, f.review_count || ' user reviews', 'No user reviews') ELSE (SELECT label FROM review_score AS r WHERE r.review_score = f.review_score) END AS "review_score_label",
    l.review_count AS "language_review_count",
    l.percent_positive AS "language_percent_positive",
    l.review_score AS "language_review_score",
    CASE WHEN l.review_score = 0 THEN IIF(l.review_count > 0, l.review_count || ' user reviews', 'No user reviews') ELSE (SELECT label FROM review_score AS r WHERE r.review_score = l.review_score) END AS "language_review_score_label",
    u.review_count AS "unfiltered_review_count",
    u.percent_positive AS "unfiltered_percent_positive",
    u.review_score AS "unfiltered_review_score",
    CASE WHEN u.review_score = 0 THEN IIF(u.review_count > 0, u.review_count || ' user reviews', 'No user reviews') ELSE (SELECT label FROM review_score AS r WHERE r.review_score = u.review_score) END AS "unfiltered_review_score_label",
    IIF(o.kind = 'package', o.id, NULL) AS "packageid",
    x.name AS "purchase_option_name",
    p.final_price_in_cents AS "final_price_in_cents",
    CASE WHEN p.final_price_in_cents IS NULL THEN NULL WHEN a.store_country = 'BR' THEN 'R$' || replace(printf('%,d', p.final_price_in_cents / 100), ',', '.') || ',' || printf('%02d', p.final_price_in_cents % 100) ELSE '$' || printf('%,d', p.final_price_in_cents / 100) || '.' || printf('%02d', p.final_price_in_cents % 100) END AS "formatted_final_price",
    p.user_can_purchase_as_gift AS "user_can_purchase_as_gift",
    p.hide_discount_pct_for_compliance AS "hide_discount_pct_for_compliance",
    p.included_game_count AS "included_game_count",
    x.must_purchase_as_set AS "must_purchase_as_set",
    o.package_group AS "package_group",
    p.price_cannot_be_displayed_as_discount AS "price_cannot_be_displayed_as_discount",
    x.free_with_master_sub_appid AS "free_with_master_sub_appid",
    p.original_price_in_cents AS "original_price_in_cents",
    CASE WHEN p.original_price_in_cents IS NULL THEN NULL WHEN a.store_country = 'BR' THEN 'R$' || replace(printf('%,d', p.original_price_in_cents / 100), ',', '.') || ',' || printf('%02d', p.original_price_in_cents % 100) ELSE '$' || printf('%,d', p.original_price_in_cents / 100) || '.' || printf('%02d', p.original_price_in_cents % 100) END AS "formatted_original_price",
    p.discount_pct AS "discount_pct",
    IIF(o.kind = 'bundle', o.id, NULL) AS "bundleid",
    p.bundle_discount_pct AS "bundle_discount_pct",
    p.price_before_bundle_discount AS "price_before_bundle_discount",
    CASE WHEN p.price_before_bundle_discount IS NULL THEN NULL WHEN a.store_country = 'BR' THEN 'R$' || replace(printf('%,d', p.price_before_bundle_discount / 100), ',', '.') || ',' || printf('%02d', p.price_before_bundle_discount % 100) ELSE '$' || printf('%,d', p.price_before_bundle_discount / 100) || '.' || printf('%02d', p.price_before_bundle_discount % 100) END AS "formatted_price_before_bundle_discount",
    p.combined_discount_pct AS "combined_discount_pct",
    a.steam_release_date AS "steam_release_date",
    a.original_release_date AS "original_release_date",
    a.original_steam_release_date AS "original_steam_release_date",
    a.custom_release_date_message AS "custom_release_date_message",
    a.coming_soon_display AS "coming_soon_display",
    a.mac_release_date AS "mac_release_date",
    CAST(strftime('%s', a.release_from_early_access_date) AS INTEGER) AS "release_from_early_access_date",
    a.release_from_early_access_style AS "release_from_early_access_style",
    a.linux_release_date AS "linux_release_date",
    a.is_preload AS "is_preload",
    t.short_description AS "short_description",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT IIF(c.creator_id IS NULL, json_object('name', c.name), json_object('name', c.name, 'creator_clan_account_id', c.creator_id)) AS item FROM app_credit AS ac JOIN credit AS c USING (credit_id) WHERE ac.appid = a.appid AND ac.role = 'publisher' ORDER BY ac.position)), '[]') AS "publishers",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT IIF(c.creator_id IS NULL, json_object('name', c.name), json_object('name', c.name, 'creator_clan_account_id', c.creator_id)) AS item FROM app_credit AS ac JOIN credit AS c USING (credit_id) WHERE ac.appid = a.appid AND ac.role = 'developer' ORDER BY ac.position)), '[]') AS "developers",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT IIF(c.creator_id IS NULL, json_object('name', c.name), json_object('name', c.name, 'creator_clan_account_id', c.creator_id)) AS item FROM app_credit AS ac JOIN credit AS c USING (credit_id) WHERE ac.appid = a.appid AND ac.role = 'franchise' ORDER BY ac.position)), '[]') AS "franchises",
    t.capsule_headline AS "capsule_headline",
    a.windows AS "windows",
    a.steam_deck_compat_category AS "steam_deck_compat_category",
    a.steam_os_compat_category AS "steam_os_compat_category",
    a.steam_frame_compat_category AS "steam_frame_compat_category",
    a.steam_machine_compat_category AS "steam_machine_compat_category",
    a.mac AS "mac",
    a.steamos_linux AS "steamos_linux",
    a.vr_vrhmd AS "vr_support.vrhmd",
    a.vr_htc_vive AS "vr_support.htc_vive",
    a.vr_oculus_rift AS "vr_support.oculus_rift",
    a.vr_windows_mr AS "vr_support.windows_mr",
    a.vr_valve_index AS "vr_support.valve_index",
    a.vr_show_optional_vr_mode_notice AS "vr_support.show_optional_vr_mode_notice",
    a.vr_vrhmd_only AS "vr_support.vrhmd_only",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT IIF(r.label IS NULL, json_object('appid', r.related_appid, 'show_above_purchase', json(IIF(r.show_above_purchase, 'true', 'false'))), json_object('appid', r.related_appid, 'label', r.label, 'show_above_purchase', json(IIF(r.show_above_purchase, 'true', 'false')))) AS item FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'demo' ORDER BY r.related_appid)), '[]') AS "demos",
    a.parent_appid AS "parent_appid",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT r.related_appid AS item FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'dlc_parent' ORDER BY r.related_appid)), '[]') AS "dlc_parent_appids",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT IIF(r.label IS NULL, json_object('appid', r.related_appid, 'show_above_purchase', json(IIF(r.show_above_purchase, 'true', 'false'))), json_object('appid', r.related_appid, 'label', r.label, 'show_above_purchase', json(IIF(r.show_above_purchase, 'true', 'false')))) AS item FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'standalone_demo' ORDER BY r.related_appid)), '[]') AS "standalone_demos",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT IIF(r.is_open IS NULL, json_object('appid', r.related_appid), json_object('appid', r.related_appid, 'is_open', json(IIF(r.is_open, 'true', 'false')))) AS item FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'playtest' ORDER BY r.related_appid)), '[]') AS "playtests",
    (SELECT r.related_appid FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'related_f2p') AS "related_f2p.appid",
    (SELECT r.header_text FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'related_f2p') AS "related_f2p.header_text",
    (SELECT r.description_text FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'related_f2p') AS "related_f2p.description_text",
    a.rating AS "rating",
    a.agency AS "agency",
    a.banned AS "banned",
    a.esrb_online_music_not_rated AS "esrb_online_music_not_rated",
    a.esrb_online_interactions_not_rated AS "esrb_online_interactions_not_rated",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT e.element AS item FROM app_interactive_element AS e WHERE e.appid = a.appid ORDER BY e.element)), '[]') AS "survey_interactive_elements",
    a.required_age AS "required_age",
    a.use_age_gate AS "use_age_gate",
    a.agency_rating AS "agency_rating",
    (SELECT r.rating_type FROM rating_agency AS r WHERE r.agency = a.agency) AS "rating_type",
    a.vetted AS "extra.vetted",
    a.has_community_hub AS "extra.has_community_hub",
    a.website AS "website",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT d.document AS item FROM app_document AS d WHERE d.appid = a.appid ORDER BY d.document)), '[]') AS "extra.links_and_info.available_documents",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT g.genreid AS item FROM app_genre AS g WHERE g.appid = a.appid ORDER BY g.position)), '[]') AS "extra.links_and_info.genreids",
    a.metacritic_score AS "metacritic_score",
    a.metacritic_url AS "metacritic_url",
    a.metacritic_always_show AS "extra.metacritic.always_show",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT e.element AS item FROM app_interactive_element AS e WHERE e.appid = a.appid ORDER BY e.element)), '[]') AS "extra.interactive_elements",
    a.drm_third_party_type AS "extra.drm_third_party_type",
    a.achievements_visible AS "extra.links_and_info.achievements_visible",
    a.achievement_count AS "achievement_count",
    a.points_shop_eligible AS "extra.points_shop_eligible",
    a.controller_wizard_complete AS "extra.controller_wizard_complete",
    a.anticheat_kernel_mode AS "extra.anticheat.kernel_mode",
    a.anticheat_name AS "extra.anticheat.name",
    (SELECT r.name_loc FROM anticheat AS r WHERE r.name = a.anticheat_name) AS "extra.anticheat.name_loc",
    a.stats_url AS "extra.links_and_info.stats_url",
    a.online_manual_url AS "extra.links_and_info.online_manual_url",
    a.privacy_policy_url AS "extra.links_and_info.privacy_policy_url",
    a.item_store_eligible AS "extra.item_store_eligible",
    a.item_store_show_featured AS "extra.item_store_show_featured",
    a.user_account_third_party AS "extra.user_account_third_party",
    a.user_account_third_party_link_to_steam AS "extra.user_account_third_party_link_to_steam",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT json_quote(m.name) AS item FROM app_manufacturer AS m WHERE m.appid = a.appid ORDER BY m.position)), '[]') AS "extra.links_and_info.manufacturers",
    a.health_warning_url AS "extra.links_and_info.health_warning_url",
    a.anticheat_uninstall_completely AS "extra.anticheat.uninstall_completely",
    NULLIF((SELECT json_group_array(json(item)) FROM (SELECT json_object('voteid', w.voteid, 'award_year', w.award_year, 'localization', json_object('title', w.title)) AS item FROM app_steam_award AS w WHERE w.appid = a.appid ORDER BY w.position)), '[]') AS "extra.steam_award",
    a.ai_generation_service_name AS "extra.ai_generation_service.name",
    a.ai_generation_service_url AS "extra.ai_generation_service.url",
    a.no_mouse_keyboard_support AS "extra.no_mouse_keyboard_support",
    a.refund_checks_ea_playtime AS "extra.refund_checks_ea_playtime",
    a.anticheat_boot_protection AS "extra.anticheat.boot_protection",
    a.anticheat_boot_protection_name AS "extra.anticheat.boot_protection_name",
    (SELECT r.related_appid FROM app_related AS r WHERE r.appid = a.appid AND r.kind = 'season_pass') AS "extra.season_pass.appid"
FROM followed_app AS w
JOIN app AS n ON n.appid = w.appid
LEFT JOIN app AS a ON a.appid = w.appid
LEFT JOIN app_text AS t ON t.appid = a.appid
LEFT JOIN app_review_summary AS f ON f.appid = a.appid AND f.scope = 'filtered'
LEFT JOIN app_review_summary AS l ON l.appid = a.appid AND l.scope = 'language'
LEFT JOIN app_review_summary AS u ON u.appid = a.appid AND u.scope = 'unfiltered'
LEFT JOIN app_offer AS o ON o.appid = a.appid AND o.is_best
LEFT JOIN offer AS x ON x.kind = o.kind AND x.id = o.id
LEFT JOIN offer_price AS p ON p.kind = o.kind AND p.id = o.id AND p.country = a.store_country
LEFT JOIN app_review_total AS s ON s.appid = n.appid;
